<template>
  <div class="page-alert-rule-list">
    <CrudToolbar :title="t('alerts.title')" :can-create="authStore.isAdmin" @create="onCreate" />

    <el-card>
      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="rules"
        :loading="loading"
        :server-side="true"
        :total="total"
      >
        <el-table-column prop="name" :label="t('common.name')" min-width="160" />
        <el-table-column prop="scope" :label="t('alerts.scope')" width="110" />
        <el-table-column prop="condition_type" :label="t('alerts.conditionType')" width="110" />
        <el-table-column prop="severity" :label="t('common.severityLabel')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.severity" type="severity" />
          </template>
        </el-table-column>
        <el-table-column prop="enabled" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.enabled ? 'success' : 'info'" size="small">
              {{ row.enabled ? t('common.enabled') : t('common.disabled') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="260" fixed="right">
          <template #default="{ row }">
            <el-button v-if="authStore.isAdmin" link type="primary" size="small" @click="onEdit(row)">
              {{ t('common.edit') }}
            </el-button>
            <el-button v-if="authStore.isAdmin" link type="primary" size="small" @click="onToggle(row)">
              {{ row.enabled ? t('common.disable') : t('common.enable') }}
            </el-button>
            <el-button link type="primary" size="small" @click="onEvaluate(row)">
              {{ t('common.test') }}
            </el-button>
            <ConfirmButton
              v-if="authStore.isAdmin"
              :title="t('alerts.confirmDeleteRule')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <AlertRuleFormDialog v-model="dialogVisible" :rule="selectedRule" @success="loadRules" />
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import {
  deleteAlertRule,
  evaluateAlertRule,
  getAlertRules,
  toggleAlertRule,
  type AlertRuleRead,
} from '@/api/alertRules'
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { useListQuery } from '@/composables/useListQuery'
import StatusTag from '@/components/common/StatusTag.vue'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import AlertRuleFormDialog from './AlertRuleFormDialog.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

const rules = ref<AlertRuleRead[]>([])
const total = ref(0)
const loading = ref(false)
const dialogVisible = ref(false)
const selectedRule = ref<AlertRuleRead | null>(null)

const { page, pageSize } = useListQuery({
  defaults: {},
  parse: () => ({}),
  serialize: () => ({}),
})

async function loadRules() {
  loading.value = true
  try {
    const response = await getAlertRules({
      page: page.value,
      page_size: pageSize.value,
    })
    rules.value = response.items
    total.value = response.total
  } catch (error) {
    showError(error, t('alerts.loadRulesFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  selectedRule.value = null
  dialogVisible.value = true
}

function onEdit(row: AlertRuleRead) {
  selectedRule.value = row
  dialogVisible.value = true
}

async function onToggle(row: AlertRuleRead) {
  try {
    await toggleAlertRule(row.id)
    ElMessage.success(t('alerts.statusUpdated'))
    loadRules()
  } catch (error) {
    showError(error, t('alerts.toggleFailed'))
  }
}

async function onDelete(row: AlertRuleRead) {
  try {
    await deleteAlertRule(row.id)
    ElMessage.success(t('alerts.ruleDeleted'))
    loadRules()
  } catch (error) {
    showError(error, t('alerts.deleteRuleFailed'))
  }
}

async function onEvaluate(row: AlertRuleRead) {
  try {
    const { value } = await ElMessageBox.prompt(t('alerts.evaluatePrompt'), t('alerts.evaluateTitle'), {
      confirmButtonText: t('common.execute'),
      cancelButtonText: t('common.cancel'),
      inputPattern: /\S+/,
      inputErrorMessage: t('alerts.nodeIdRequired'),
    })
    const result = await evaluateAlertRule(row.id, value)
    ElMessage.success(t('alerts.evaluateResult', { state: result.state }))
  } catch (error: any) {
    if (error === 'cancel') return
    showError(error, t('alerts.evaluateFailed'))
  }
}

useRealtimeRefresh(loadRules, ['alerts'], { notifyEventTypes: ['alert.firing'] })

watch(
  () => ({ page: page.value, pageSize: pageSize.value }),
  loadRules,
  { deep: true, immediate: true }
)
</script>
