<template>
  <el-dialog
    v-model="visible"
    :title="isEdit ? t('alerts.form.editTitle') : t('alerts.form.createTitle')"
    width="720px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="140px">
      <el-form-item :label="t('alerts.form.ruleName')" prop="name">
        <el-input v-model="form.name" :placeholder="t('alerts.form.ruleNamePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('alerts.form.scopeLabel')" prop="scope">
        <el-select v-model="form.scope" :placeholder="t('alerts.form.scopePlaceholder')" @change="onScopeChange">
          <el-option :label="t('alerts.form.scopeGlobal')" value="global" />
          <el-option :label="t('alerts.form.scopeNode')" value="node" />
          <el-option :label="t('alerts.form.scopeNodeGroup')" value="node_group" />
        </el-select>
      </el-form-item>
      <el-form-item v-if="form.scope === 'node'" :label="t('alerts.form.targetNode')" prop="scope_target">
        <el-select v-model="form.scope_target" :placeholder="t('alerts.form.selectNode')" filterable>
          <el-option
            v-for="node in nodes"
            :key="node.node_id"
            :label="`${node.name} (${node.node_id})`"
            :value="node.node_id"
          />
        </el-select>
      </el-form-item>
      <el-form-item v-if="form.scope === 'node_group'" :label="t('alerts.form.targetNodeGroup')" prop="scope_target">
        <el-select v-model="form.scope_target" :placeholder="t('alerts.form.selectNodeGroup')">
          <el-option
            v-for="group in nodeGroups"
            :key="group.id"
            :label="group.name"
            :value="String(group.id)"
          />
        </el-select>
      </el-form-item>
      <el-form-item :label="t('alerts.conditionType')" prop="condition_type">
        <el-radio-group v-model="form.condition_type">
          <el-radio value="json_dsl">JSON DSL</el-radio>
          <el-radio value="promql">PromQL</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('alerts.form.condition')" prop="condition">
        <CodeEditor v-model="form.condition" :rows="6" :placeholder="conditionPlaceholder" />
      </el-form-item>
      <el-form-item :label="t('alerts.form.pendingDuration')">
        <el-input-number v-model="form.pending_duration_seconds" :min="0" :step="10" />
        <span style="margin-left: 8px; color: var(--el-text-color-secondary)">{{ t('common.seconds') }}</span>
      </el-form-item>
      <el-form-item :label="t('alerts.form.resolveDuration')">
        <el-input-number v-model="form.resolve_duration_seconds" :min="0" :step="10" />
        <span style="margin-left: 8px; color: var(--el-text-color-secondary)">{{ t('common.seconds') }}</span>
      </el-form-item>
      <el-form-item :label="t('common.severityLabel')" prop="severity">
        <el-radio-group v-model="form.severity">
          <el-radio value="critical">{{ t('common.critical') }}</el-radio>
          <el-radio value="warning">{{ t('common.warning') }}</el-radio>
          <el-radio value="info">{{ t('common.info') }}</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('alerts.form.notifyChannels')">
        <el-select
          v-model="form.notification_channel_ids"
          multiple
          :placeholder="t('alerts.form.notifyChannelsPlaceholder')"
          style="width: 100%"
        >
          <el-option
            v-for="channel in channels"
            :key="channel.id"
            :label="channel.name"
            :value="channel.id"
          />
        </el-select>
      </el-form-item>
      <el-form-item :label="t('alerts.form.enableRule')">
        <el-switch v-model="form.enabled" />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">
        {{ isEdit ? t('common.save') : t('common.create') }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  createAlertRule,
  updateAlertRule,
  type AlertRuleCreate,
  type AlertRuleRead,
  type AlertRuleScope,
  type AlertRuleSeverity,
  type AlertRuleConditionType,
} from '@/api/alertRules'
import { getNodes, type NodeRead } from '@/api/nodes'
import { getNodeGroups, type NodeGroupRead } from '@/api/nodeGroups'
import { getNotificationChannels, type NotificationChannelRead } from '@/api/notificationChannels'
import CodeEditor from '@/components/common/CodeEditor.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
  rule?: AlertRuleRead | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: []
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()
const nodes = ref<NodeRead[]>([])
const nodeGroups = ref<NodeGroupRead[]>([])
const channels = ref<NotificationChannelRead[]>([])
const isEdit = ref(false)

const form = ref<{
  name: string
  scope: AlertRuleScope
  scope_target: string
  condition_type: AlertRuleConditionType
  condition: string
  pending_duration_seconds: number
  resolve_duration_seconds: number
  severity: AlertRuleSeverity
  enabled: boolean
  notification_channel_ids: number[]
}>({
  name: '',
  scope: 'global',
  scope_target: '',
  condition_type: 'json_dsl',
  condition: '',
  pending_duration_seconds: 60,
  resolve_duration_seconds: 60,
  severity: 'warning',
  enabled: true,
  notification_channel_ids: [],
})

const rules: FormRules = {
  name: [{ required: true, message: () => t('alerts.form.ruleNameRequired'), trigger: 'blur' }],
  scope: [{ required: true, message: () => t('alerts.form.scopeRequired'), trigger: 'change' }],
  condition_type: [{ required: true, message: () => t('alerts.form.conditionTypeRequired'), trigger: 'change' }],
  condition: [
    { required: true, message: () => t('alerts.form.conditionRequired'), trigger: 'blur' },
    { validator: validateCondition, trigger: 'blur' },
  ],
  severity: [{ required: true, message: () => t('alerts.form.severityRequired'), trigger: 'change' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

watch(
  () => props.rule,
  (rule) => {
    if (rule) {
      isEdit.value = true
      form.value = {
        name: rule.name,
        scope: rule.scope,
        scope_target: rule.scope_target || '',
        condition_type: rule.condition_type,
        condition: rule.condition || '',
        pending_duration_seconds: rule.pending_duration_seconds,
        resolve_duration_seconds: rule.resolve_duration_seconds,
        severity: rule.severity,
        enabled: rule.enabled,
        notification_channel_ids: rule.notification_channel_ids || [],
      }
    } else {
      isEdit.value = false
      resetForm()
    }
  },
  { immediate: true }
)

onMounted(() => {
  loadOptions()
})

async function loadOptions() {
  try {
    const [nodesRes, groupsRes, channelsRes] = await Promise.all([
      getNodes({ page_size: 100 }),
      getNodeGroups(),
      getNotificationChannels(),
    ])
    nodes.value = nodesRes.items
    nodeGroups.value = groupsRes
    channels.value = channelsRes.items
  } catch (error) {
    showError(error, t('alerts.form.loadOptionsFailed'))
  }
}

const conditionPlaceholder = computed(() =>
  form.value.condition_type === 'promql'
    ? t('alerts.form.promqlPlaceholder')
    : t('alerts.form.jsonDslPlaceholder')
)

function validateCondition(_rule: unknown, value: string, callback: (error?: Error) => void) {
  if (form.value.condition_type === 'json_dsl') {
    try {
      const parsed = JSON.parse(value || '{}')
      if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
        callback(new Error(t('alerts.form.jsonDslMustBeObject')))
        return
      }
    } catch {
      callback(new Error(t('alerts.form.jsonDslInvalid')))
      return
    }
  }
  callback()
}

function resetForm() {
  form.value = {
    name: '',
    scope: 'global',
    scope_target: '',
    condition_type: 'json_dsl',
    condition: '',
    pending_duration_seconds: 60,
    resolve_duration_seconds: 60,
    severity: 'warning',
    enabled: true,
    notification_channel_ids: [],
  }
}

function onScopeChange() {
  form.value.scope_target = ''
}

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
  resetForm()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const data: AlertRuleCreate = {
      name: form.value.name,
      scope: form.value.scope,
      condition_type: form.value.condition_type,
      condition: form.value.condition,
      pending_duration_seconds: form.value.pending_duration_seconds,
      resolve_duration_seconds: form.value.resolve_duration_seconds,
      severity: form.value.severity,
      enabled: form.value.enabled,
      notification_channel_ids: form.value.notification_channel_ids,
    }
    if (form.value.scope !== 'global') {
      data.scope_target = form.value.scope_target || undefined
    }

    if (props.rule) {
      await updateAlertRule(props.rule.id, data)
    } else {
      await createAlertRule(data)
    }
    ElMessage.success(isEdit.value ? t('alerts.form.ruleUpdated') : t('alerts.form.ruleCreated'))
    emit('success')
    visible.value = false
  } catch (error) {
    showError(error, isEdit.value ? t('alerts.form.updateFailed') : t('alerts.form.createFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
