import apiClient from './client'

export interface NodeGroupRead {
  id: number
  name: string
  description?: string | null
  node_ids: string[]
  created_at: string
  updated_at: string
}

export interface NodeGroupCreate {
  name: string
  description?: string
  node_ids?: string[]
}

export interface NodeGroupUpdate {
  name?: string
  description?: string
  node_ids?: string[]
}

export async function getNodeGroups(): Promise<NodeGroupRead[]> {
  const response = await apiClient.get<NodeGroupRead[]>('/v1/node-groups')
  return response.data
}

export async function createNodeGroup(data: NodeGroupCreate): Promise<NodeGroupRead> {
  const response = await apiClient.post<NodeGroupRead>('/v1/node-groups', data)
  return response.data
}

export async function getNodeGroup(groupId: number): Promise<NodeGroupRead> {
  const response = await apiClient.get<NodeGroupRead>(`/v1/node-groups/${groupId}`)
  return response.data
}

export async function updateNodeGroup(groupId: number, data: NodeGroupUpdate): Promise<NodeGroupRead> {
  const response = await apiClient.put<NodeGroupRead>(`/v1/node-groups/${groupId}`, data)
  return response.data
}

export async function deleteNodeGroup(groupId: number): Promise<void> {
  await apiClient.delete(`/v1/node-groups/${groupId}`)
}
